(function(){
'use strict';const KEY='study-reader-views-v1';let saved={};try{saved=JSON.parse(localStorage.getItem(KEY))||{};}catch{}
function prepare(lesson,keyOverride){if(!lesson||lesson.dataset.viewsReady)return;lesson.dataset.viewsReady='true';const key=keyOverride||location.hash.split('/')[2]+':'+document.querySelector('#cs-chapter').value+':'+document.querySelector('#cs-page').value;lesson.dataset.readerKey=key;const find=s=>lesson.querySelector(lesson.dataset.prefix?s.replace(/#([\w-]+)/g,(_,id)=>'#'+lesson.dataset.prefix+id):s);
const nav=lesson.querySelector('nav[aria-label="페이지 학습 순서"]');if(!nav)return;nav.innerHTML='';nav.className='cs-view-tabs';nav.setAttribute('role','tablist');nav.setAttribute('aria-label','학습 화면');
const specs=[['explain','설명',['.cs-explain','.cs-depth']],['lab','실험',['#cs-lab-anchor','#cs-interactive']],['quiz','문제',['#cs-quiz-anchor']],['source','원문',['.cs-evidence','#cs-source-anchor']]];const panes={},buttons={};let insertAfter=nav;const range=lesson.querySelector('.cs-range');if(range)nav.before(range);
for(const[id,label,selectors]of specs){const pane=document.createElement('section');pane.className='cs-view-panel';pane.id=(lesson.dataset.prefix||'')+'cs-view-'+id;pane.setAttribute('role','tabpanel');pane.setAttribute('aria-labelledby',(lesson.dataset.prefix||'')+'cs-tab-'+id);pane.tabIndex=0;for(const selector of selectors){const n=find(selector);if(n)pane.append(n);}insertAfter.after(pane);insertAfter=pane;panes[id]=pane;const b=document.createElement('button');b.id=(lesson.dataset.prefix||'')+'cs-tab-'+id;b.type='button';b.textContent=label;b.setAttribute('role','tab');b.setAttribute('aria-controls',pane.id);b.disabled=id==='lab'?(lesson.dataset.prefix?!window.PLLab.mode(document.querySelector('#cs-chapter').value,+lesson.dataset.page):!pane.querySelector('.pl-lab,.dm-lab')):id==='quiz'?!find('#cs-quiz'):false;if(id==='quiz')b.hidden=b.disabled;nav.append(b);buttons[id]=b;}
function select(id,persist=true){if(!buttons[id]||buttons[id].disabled)id='explain';for(const[v,pane]of Object.entries(panes)){pane.hidden=v!==id;buttons[v].setAttribute('aria-selected',String(v===id));buttons[v].tabIndex=v===id?0:-1;}lesson.dataset.readerView=id;if(id!=='lab')window.PLLab?.stop();if(persist){saved[key]=id;try{localStorage.setItem(KEY,JSON.stringify(saved));}catch{}}window.Notebook?.refresh();lesson.dispatchEvent(new CustomEvent('reader-view-change',{bubbles:true}));}
function navigate(id){if(window.ReaderLinks)window.ReaderLinks.navigate(lesson,id);else select(id);}
for(const[id,b]of Object.entries(buttons)){b.onclick=()=>navigate(id);b.onkeydown=e=>{if(!['ArrowLeft','ArrowRight','Home','End'].includes(e.key))return;e.preventDefault();const enabled=Object.keys(buttons).filter(v=>!buttons[v].disabled),index=enabled.indexOf(id),next=e.key==='Home'?0:e.key==='End'?enabled.length-1:(index+(e.key==='ArrowRight'?1:-1)+enabled.length)%enabled.length;navigate(enabled[next]);buttons[enabled[next]].focus({preventScroll:true});};}
const note=lesson.querySelector('.cs-note');if(note){const d=document.createElement('details');d.className='cs-note-box';d.innerHTML='<summary>메모</summary>';note.before(d);d.append(note);}
const manage=lesson.querySelector('.cs-organizer'),tools=lesson.querySelector('.cs-toolbar');if(manage){const d=document.createElement('details');d.className='cs-manage-box';d.innerHTML='<summary>기록·편집</summary>';manage.before(d);d.append(manage);if(tools)d.append(tools);}
lesson.querySelector('.cs-explain small')?.remove();lesson.querySelector('.cs-depth>section>p')?.remove();lesson.querySelector('.cs-exam small')?.remove();const badge=lesson.querySelector('.cs-pageheading .s-status');if(badge){badge.textContent=badge.textContent.includes('안내')?'안내':badge.textContent.includes('계속')?'이어지는 예제':'개념';}
for(const p of lesson.querySelectorAll(':scope>p.s-muted'))if(p.textContent.includes('브라우저'))p.remove();
lesson.readerViews={select,buttons,panes};select(saved[key]||'explain',false);return lesson.readerViews;
}
function refresh(){if(document.querySelector('.continuous-reader'))return;prepare(document.querySelector('.cs-lesson'));}window.CourseViews={prepare};
new MutationObserver(refresh).observe(document.getElementById('school-app'),{childList:true});window.addEventListener('pageshow',refresh);refresh();
})();
